def compute(vars):
    revenue = vars["Revenue"]
    cost_of_sales = vars["Cost of Sales"]
    multiplier = vars["100"]

    if revenue == 0:
        value = None
    else:
        value = ((revenue - cost_of_sales) / revenue) * multiplier

    return {
        "value": value,
        "trace": {
            "Revenue": revenue,
            "Cost of Sales": cost_of_sales,
            "100": multiplier,
            "Gross Profit": revenue - cost_of_sales,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
